    const midDate = new Date(mid);
    const position = SunCalc.getPosition(midDate, latitude, longitude);
    const altitude = position.altitude * (180 / Math.PI);
    if (descending) {
      if (altitude > targetAltitude) {
        high = mid;
      } else {
        low = mid;
      }
    } else {
      if (altitude > targetAltitude) {
        low = mid;
      } else {
        high = mid;
      }
    }
